// FamilyLegacy2仍由原唯一账控制；真实Born打开仅提供本人会面来源，不能凭血缘自动同意。
#include "biological_control_world.hpp"
#include "collateral_control_world.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/domains/interaction/born_dialogues/born_personal_dialogue_world.hpp"
namespace hanmo::resident {namespace {
Status profile(const WorldBundle& w){
 const bool enabled=w.family_biological_legacy_enabled();Integer markers=0,legacy_markers=0;for(const auto& m:w.catalog->identity.module_versions){if(m.first=="family_biological_legacy"){++markers;if(m.second!="1")return common_failure("UnsupportedBiologicalControlVersion");}if(m.first=="family_legacy"){++legacy_markers;if(enabled&&m.second!=(w.family_collateral_legacy_enabled()?"3":"2"))return common_failure("BiologicalControlLegacyVersionRequired");}}
 if(enabled!=w.family_biological_legacy_seed_complete||bool(w.catalog->family_biological_legacy)!=enabled||markers!=(enabled?1:0))return common_failure("BiologicalControlProfileMismatch");
 if(!enabled){if(!w.family_biological_legacy.commits.empty()||(w.catalog->family_legacy&&w.catalog->family_legacy->version==2))return common_failure("BiologicalControlProfileRequired");return common_success();}
 if(!w.dynamic_enabled()||!w.family_birth_enabled()||!w.family_life_enabled()||!w.family_legacy_enabled()||!w.catalog->family->enabled||!w.catalog->family_lineage||w.catalog->family_legacy->version!=(w.family_collateral_legacy_enabled()?3:2)||legacy_markers!=1||w.catalog->interaction->common.get()!=w.catalog->common.get())return common_failure("BiologicalControlDependenciesRequired");return common_success();
}
std::optional<DiscipleControlRelationContext> disciple(const WorldBundle& w){if(!w.family_disciple_legacy_enabled())return {};return DiscipleControlRelationContext{w.common,*w.catalog->common,w.family_apprenticeship,*w.catalog->family_legacy,*w.catalog->family_disciple_legacy,w.family_apprenticeship_access()};}
}
BiologicalControlWorldAccess::BiologicalControlWorldAccess(const WorldBundle& w,std::shared_ptr<BornPersonalDialogueWorldAccess> born):world_(w),born_(std::move(born)),context_{{w.common,*w.catalog->common,*w.catalog->family_lineage,w.family_birth_enabled()?&w.family_birth:nullptr,&w.family_life,w.family_death_read()},*w.catalog->family_biological_legacy,*w.catalog->family_legacy,*w.catalog->interaction,[this](const StableId& id)->Outcome<BiologicalControlTemplateIdentity>{if(!world_.catalog->born_personal_dialogues)return {false,{},common_failure("BiologicalControlTemplateSourceRequired").error};const auto* selected=born_personal_dialogue_template(*world_.catalog->born_personal_dialogues,id);if(!selected)return {false,{},common_failure("BiologicalControlTemplateSourceRequired",id).error};return {true,{selected->id,selected->prototype_id,selected->dialogue_id},{}};},born_?&born_->read():nullptr}{}
Outcome<std::shared_ptr<BiologicalControlWorldAccess>> BiologicalControlWorldAccess::create(const WorldBundle& w){auto valid=profile(w);if(!valid.ok)return {false,{},valid.error};if(!w.family_biological_legacy_enabled())return {false,{},common_failure("BiologicalControlProfileRequired").error};bool dynamic=false;for(const auto& row:w.catalog->family_biological_legacy->definitions.rows())dynamic|=row.second.meeting_kind==BiologicalControlMeetingKind::born_personal_template;std::shared_ptr<BornPersonalDialogueWorldAccess> born;if(dynamic){auto source=BornPersonalDialogueWorldAccess::create(w);if(!source.ok)return {false,{},source.error};born=std::move(source.value);}auto out=std::shared_ptr<BiologicalControlWorldAccess>(new BiologicalControlWorldAccess(w,std::move(born)));valid=validate_biological_control_context(out->context());return valid.ok?Outcome<std::shared_ptr<BiologicalControlWorldAccess>>{true,std::move(out),{}}:Outcome<std::shared_ptr<BiologicalControlWorldAccess>>{false,{},valid.error};}
Status validate_family_biological_world(const WorldBundle& w){auto valid=profile(w);if(!valid.ok||!w.family_biological_legacy_enabled())return valid;auto access=BiologicalControlWorldAccess::create(w);if(!access.ok)return {false,{},access.error};std::shared_ptr<CollateralControlWorldAccess> collateral;if(w.family_collateral_legacy_enabled()){auto selected=CollateralControlWorldAccess::create(w);if(!selected.ok)return {false,{},selected.error};collateral=std::move(selected.value);}auto relation=disciple(w);valid=validate_family_legacy(w.common,w.family,w.family_life,w.family_death_read(),*w.catalog->common,*w.catalog->interaction,*w.catalog->family_legacy,w.family_legacy,w.family_legacy_playable_read(),relation?&*relation:nullptr,&access.value->context(),collateral?&collateral->context():nullptr);if(!valid.ok)return valid;return validate_biological_control_result_bindings(w.common,w.family_legacy,*w.catalog->family_biological_legacy,w.family_biological_legacy);}
Status bind_family_biological_result_world(WorldBundle& w,const FamilyLegacyState* before,const BiologicalControlState* bindings,const StableId& actor,Integer request,const CommitResult& result){if(!w.family_biological_legacy_enabled())return before||bindings?common_failure("BiologicalControlProfileRequired"):common_success();auto valid=profile(w);if(!valid.ok)return valid;if(!before||!bindings)return common_failure("BiologicalControlBeforeStateRequired");return bind_biological_control_result_in_candidate(w.common,*before,w.family_legacy,*w.catalog->family_biological_legacy,*bindings,w.family_biological_legacy,actor,request,result,w.family_collateral_legacy_enabled()?FamilyLegacyVersion::collateral3:FamilyLegacyVersion::biological2);}
Outcome<LegacyControlDecisionQuote> preview_family_biological_world(const WorldBundle& w,const StableId& actor,const BiologicalControlCommand& command){auto access=BiologicalControlWorldAccess::create(w);if(!access.ok)return {false,{},access.error};std::shared_ptr<CollateralControlWorldAccess> collateral;if(w.family_collateral_legacy_enabled()){auto selected=CollateralControlWorldAccess::create(w);if(!selected.ok)return {false,{},selected.error};collateral=std::move(selected.value);}auto relation=disciple(w);auto interaction=w.services.interaction_access();return preview_biological_control_command(access.value->context(),w.family,w.family_life,w.family_death_read(),w.interaction,interaction,w.family_legacy,w.family_legacy_playable_read(),actor,command,relation?&*relation:nullptr,collateral?&collateral->context():nullptr);}
Outcome<FamilyEffect> apply_family_biological_world(WorldBundle& w,const StableId& actor,const BiologicalControlCommand& command,const LegacyControlDecisionQuote& quote){auto access=BiologicalControlWorldAccess::create(w);if(!access.ok)return {false,{},access.error};std::shared_ptr<CollateralControlWorldAccess> collateral;if(w.family_collateral_legacy_enabled()){auto selected=CollateralControlWorldAccess::create(w);if(!selected.ok)return {false,{},selected.error};collateral=std::move(selected.value);}auto relation=disciple(w);auto interaction=w.services.interaction_access();return apply_biological_control_command(w.common,access.value->context(),w.family,w.family_life,w.family_death_read(),w.interaction,interaction,w.family_legacy,w.family_legacy_playable_read(),actor,command,quote,relation?&*relation:nullptr,collateral?&collateral->context():nullptr);}
Outcome<BoundaryValue> query_family_biological_world(const WorldBundle& w,Integer page){auto access=BiologicalControlWorldAccess::create(w);if(!access.ok)return {false,{},access.error};std::shared_ptr<CollateralControlWorldAccess> collateral;if(w.family_collateral_legacy_enabled()){auto selected=CollateralControlWorldAccess::create(w);if(!selected.ok)return {false,{},selected.error};collateral=std::move(selected.value);}auto relation=disciple(w);auto interaction=w.services.interaction_access();return query_biological_control_page(access.value->context(),w.family,w.family_life,w.family_death_read(),w.interaction,interaction,w.family_legacy,w.family_legacy_playable_read(),page,relation?&*relation:nullptr,collateral?&collateral->context():nullptr);}
}
